select d.number, j.id jid, to_char(j.at,'HH24:MI:SS.MS') at, j.action, j.by_crm_user_id as by, j.comment from journal j join documents d on d.id=j.document_id where d.number like 'СЗ-%' order by d.number, j.id;
select o.type, to_char(o.created_at,'HH24:MI:SS.MS') created, o.envelope->'data'->>'number' as number, o.envelope->'data'->'step'->>'index' as step_idx, o.envelope->'data'->>'decision' as decision, o.id from rt_bus_outbox o where o.type in ('uz.railtech.eds.approval.requested.v1','uz.railtech.eds.approval.decided.v1','uz.railtech.eds.document.registered.v1','uz.railtech.eds.document.archived.v1') order by o.created_at;
